class Solution {
private:
    int maxLength = 0;

    int dfs(TreeNode* p) {
        if (p == nullptr) return 0;

        int L = dfs(p->left) + 1;
        int R = dfs(p->right) + 1;

        if (p->left != nullptr && p->val + 1 != p->left->val) {
            L = 1;
        }

        if (p->right != nullptr && p->val + 1 != p->right->val) {
            R = 1;
        }

        int length = max(L, R);
        maxLength = max(maxLength, length);

        return length;
    }

public:
    int longestConsecutive(TreeNode* root) {
        dfs(root);
        return maxLength;
    }
};
